#!/usr/bin/env bash
# Generated by ClickStarDeploy. Do not edit: it is rewritten on every apply.
# Waits until a pushed commit is live on the website (or its deploy failed) and says why.
#   bash .autodeploy/wait-deploy.sh [commit]     (default: HEAD)
# Exit: 0 live, 1 deploy failed, 3 commit not pushed to the deploy branch, 4 ClickStarDeploy unreachable,
# 5 still deploying after AD_WAIT_MAX seconds.
set -u
AD_URL='https://gitlab.clickstar.vn:8443'
# "branch project site" per line: production first, then environments such as dev.
AD_TARGETS='main adf2d2638d70 https://dev.clickstar.vn'
MAX_SECONDS=${AD_WAIT_MAX:-1800}

cd "$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
sha=$(git rev-parse "${1:-HEAD}" 2>/dev/null) || { echo "ClickStarDeploy: không đọc được commit ${1:-HEAD}"; exit 3; }
# Which environment: $AD_BRANCH or the current branch when it deploys, else the first deploy
# branch on origin that already has this commit.
target_of() { printf '%s\n' "$AD_TARGETS" | awk -v b="$1" '$1 == b' | head -n 1; }
target=$(target_of "${AD_BRANCH:-$(git rev-parse --abbrev-ref HEAD 2>/dev/null)}")
if [ -z "$target" ]; then
  for b in $(printf '%s\n' "$AD_TARGETS" | awk '{print $1}'); do
    r=$(git ls-remote origin "refs/heads/$b" 2>/dev/null | cut -f1)
    if [ -n "$r" ] && { [ "$r" = "$sha" ] || git merge-base --is-ancestor "$sha" "$r" 2>/dev/null; }; then target=$(target_of "$b"); break; fi
  done
fi
[ -n "$target" ] || target=$(printf '%s\n' "$AD_TARGETS" | head -n 1)
read -r AD_BRANCH AD_PROJECT AD_SITE <<EOF
$target
EOF
remote=$(git ls-remote origin "refs/heads/$AD_BRANCH" 2>/dev/null | cut -f1)
if [ -z "$remote" ]; then
  echo "ClickStarDeploy: không đọc được nhánh $AD_BRANCH trên origin (chưa push, hoặc không có mạng)."; exit 3
fi
if [ "$remote" != "$sha" ]; then
  git cat-file -e "$remote^{commit}" 2>/dev/null || git fetch -q origin "$AD_BRANCH" 2>/dev/null || true
  if ! git merge-base --is-ancestor "$sha" "$remote" 2>/dev/null; then
    echo "ClickStarDeploy: commit ${sha:0:8} chưa có trên nhánh $AD_BRANCH của origin, nên chưa được deploy."
    echo "Website chỉ cập nhật sau khi push lên $AD_BRANCH (git push origin HEAD:$AD_BRANCH)."
    exit 3
  fi
  # A newer commit is on top of ours: its deploy is the one that ships our change.
  sha=$remote
fi

value() { printf '%s\n' "$resp" | sed -n "s/^$1=//p" | head -n 1; }
start=$(date +%s); last=""; errors=0; pulled=0
echo "ClickStarDeploy: chờ deploy commit ${sha:0:8} lên $AD_SITE ..."
while :; do
  resp=$(curl -sS --max-time 75 "$AD_URL/deploy-status/$AD_PROJECT/$sha?wait=50" 2>&1)
  state=$(value state)
  if [ -z "$state" ]; then
    errors=$((errors + 1))
    if [ $errors -ge 4 ]; then echo "ClickStarDeploy: không hỏi được trạng thái deploy ($resp). Xem trên dashboard ClickStarDeploy."; exit 4; fi
    sleep 5; continue
  fi
  errors=0
  elapsed=$(( $(date +%s) - start ))
  msg=$(value message)
  if [ "$state $msg" != "$last" ]; then echo "  [${elapsed}s] $msg"; last="$state $msg"; fi
  case $state in
    success)
      echo "ClickStarDeploy: ĐÃ LIVE. Commit ${sha:0:8} đang chạy trên $AD_SITE (pipeline $(value pipeline))."
      [ $pulled = 1 ] && echo "ClickStarDeploy đã tự commit bản sửa script deploy lên $AD_BRANCH: chạy 'git pull' trước khi sửa tiếp."
      exit 0 ;;
    fixing)
      # ClickStarDeploy's AI fixed .autodeploy/deploy.sh and pushed a new commit: follow that one.
      next=$(value fix_sha)
      if [ -n "$next" ] && [ "$next" != "$sha" ]; then sha=$next; pulled=1; echo "  ClickStarDeploy tự sửa script deploy (commit ${sha:0:8}), chờ lần deploy mới..."; fi
      sleep 3 ;;
    failed|canceled)
      echo "ClickStarDeploy: DEPLOY LỖI, website vẫn chạy bản cũ. Pipeline: $(value pipeline)"
      printf '%s\n' "$resp" | sed -n 's/^\(category\|summary\|suggestion\)=/  \1: /p'
      printf '%s\n' "$resp" | sed -n '/^--- log ---$/,$p'
      [ $pulled = 1 ] && echo "ClickStarDeploy đã commit thêm lên $AD_BRANCH: chạy 'git pull' trước khi sửa."
      exit 1 ;;
    unknown)
      if [ $elapsed -gt 120 ]; then echo "ClickStarDeploy: không thấy pipeline nào cho commit ${sha:0:8} (commit có [skip ci]?)."; exit 1; fi
      sleep 5 ;;
  esac
  if [ $elapsed -gt "$MAX_SECONDS" ]; then echo "ClickStarDeploy: đã chờ $((MAX_SECONDS / 60)) phút, deploy VẪN ĐANG CHẠY (chưa live). Pipeline: $(value pipeline). Chạy lại: bash .autodeploy/wait-deploy.sh $sha"; exit 5; fi
done
